partner_router = APIRouter(
    prefix="/partner",
    dependencies=[Depends(require_reseller_role)]
)

@partner_router.post("/reseller/clients/{client_id}/suspend")
def suspend_reseller_client(
    client_id: int,
    reseller: ResellerAccount = Depends(get_current_reseller),
    db: Session = Depends(get_db)
):
    client = db.query(ClientCompany).filter(
        ClientCompany.id == client_id,
        ClientCompany.reseller_id == reseller.id
    ).first()
    if not client:
        raise HTTPException(status_code=404, detail="Client company not found")

    client.is_suspended = True
    db.commit()
    return {"status": "suspended", "client_id": client_id}
